fn dark_matrix(case: &GoldenCase) -> Vec<u8> {
    let mut v = Vec::with_capacity(case.w * case.h);
    for line in case.matrix.split("\n") {
        assert_eq!(line.len(), case.w, "{:?} line width", case.payload);
        for ch in line.chars() {
            v.push(if ch == '#' { 1 } else { 0 });
        }
    }
    assert_eq!(v.len(), case.w * case.h);
    v
}

#[test]
fn golden_streams() {
    for case in CASES {
        let dark = dark_matrix(case);
        let stream = read_exact(&dark, case.w, case.h)
            .unwrap_or_else(|| panic!("{:?}: no stream", case.payload));
        assert_eq!(stream, case.stream, "{:?} stream", case.payload);
    }
}

#[test]
fn golden_text() {
    for case in CASES {
        let dark = dark_matrix(case);
        let text = decode_exact(&dark, case.w, case.h)
            .unwrap_or_else(|| panic!("{:?}: no text", case.payload));
        assert_eq!(text, case.payload.as_bytes(), "{:?} text", case.payload);
    }
}

#[test]
fn golden_descriptor_counts_data_and_pads() {
    for case in CASES {
        let dark = dark_matrix(case);
        let stream = read_exact(&dark, case.w, case.h).unwrap();
        let (desc, data_pads, _ecc) = split_stream(&stream).unwrap();
        assert_eq!(desc as usize, 1 + data_pads.len(), "{:?}", case.payload);
        let text = decode_text(strip_pads(data_pads)).unwrap();
        assert_eq!(text, case.payload, "{:?}", case.payload);
    }
}

use barcode_pdf417::rs::{k_for_level, rs_encode, rs_valid};

/// (payload, level, message, ecc) -- GENERATED from zint oracle streams.
/// message = descriptor + data + pads (row indicators excluded);
/// ecc = complement of the RS remainder, spec 2.6.3.
const RS_VECTORS: &[(&str, u8, &[u16], &[u16])] = &[
    ("A1", 0, &[3, 28, 59], &[208, 633]),
    ("HELLO WORLD 99", 0, &[10, 214, 341, 446, 674, 521, 116, 849, 299, 900], &[924, 831]),
    ("PDF417 RS", 2, &[8, 453, 178, 121, 236, 857, 569, 900], &[221, 407, 213, 352, 769, 832, 792, 528]),
    ("The quick brown fox jumps over the lazy dog", 5, &[26, 597, 214, 796, 608, 70, 781, 524, 673, 785, 443, 789, 612, 468, 794, 634, 536, 577, 146, 330, 774, 783, 426, 900, 900, 900], &[309, 350, 220, 55, 723, 170, 624, 572, 89, 919, 241, 439, 763, 859, 384, 405, 473, 57, 542, 251, 4, 816, 64, 453, 20, 888, 286, 318, 161, 704, 223, 225, 528, 596, 214, 251, 572, 197, 148, 781, 878, 449, 464, 384, 829, 583, 41, 401, 801, 46, 823, 532, 608, 234, 550, 225, 740, 849, 519, 492, 545, 828, 343, 524]),
];

#[test]
fn rs_encoder_matches_oracle() {
    for (payload, level, message, ecc) in RS_VECTORS {
        let k = k_for_level(*level);
        assert_eq!(k, ecc.len(), "{:?} k", payload);
        assert_eq!(&rs_encode(message, k), ecc, "{:?} ecc", payload);
    }
}

#[test]
fn rs_validates_oracle_streams() {
    for (payload, level, message, ecc) in RS_VECTORS {
        let mut full = message.to_vec();
        full.extend_from_slice(ecc);
        assert!(rs_valid(&full, k_for_level(*level)), "{:?} valid", payload);
    }
}

#[test]
fn rs_rejects_corruption() {
    for (payload, level, message, ecc) in RS_VECTORS {
        let mut full = message.to_vec();
        full.extend_from_slice(ecc);
        // corrupt one data codeword and one ecc codeword
        full[1] = (full[1] + 1) % 929;
        assert!(!rs_valid(&full, k_for_level(*level)), "{:?} data corrupt", payload);
        let mut full2 = message.to_vec();
        full2.extend_from_slice(ecc);
        let last = full2.len() - 1;
        full2[last] = (full2[last] + 1) % 929;
        assert!(!rs_valid(&full2, k_for_level(*level)), "{:?} ecc corrupt", payload);
    }
}

/// (payload, level, full stream, [(pos, delta)] applied to corrupt) --
/// GENERATED; correction must restore the original exactly.
const RS_CORRUPTIONS: &[(&str, u8, &[u16], &[(usize, u16)])] = &[
    ("PDF417 RS", 2, &[8, 453, 178, 121, 236, 857, 569, 900, 221, 407, 213, 352, 769, 832, 792, 528], &[(10, 102), (12, 404), (13, 362)]),
    ("The quick brown fox jumps over the lazy dog", 5, &[26, 597, 214, 796, 608, 70, 781, 524, 673, 785, 443, 789, 612, 468, 794, 634, 536, 577, 146, 330, 774, 783, 426, 900, 900, 900, 309, 350, 220, 55, 723, 170, 624, 572, 89, 919, 241, 439, 763, 859, 384, 405, 473, 57, 542, 251, 4, 816, 64, 453, 20, 888, 286, 318, 161, 704, 223, 225, 528, 596, 214, 251, 572, 197, 148, 781, 878, 449, 464, 384, 829, 583, 41, 401, 801, 46, 823, 532, 608, 234, 550, 225, 740, 849, 519, 492, 545, 828, 343, 524], &[(2, 92), (3, 314), (6, 357), (7, 171), (9, 410), (11, 37), (12, 153), (16, 895), (19, 98), (20, 623), (24, 217), (25, 6), (32, 444), (34, 594), (35, 850), (47, 785), (48, 346), (50, 206), (51, 865), (52, 794), (55, 863), (63, 142), (64, 552), (69, 455), (71, 903), (72, 224), (73, 588), (77, 40), (78, 61), (83, 380), (88, 445)]),
];

#[test]
fn rs_corrects_at_full_capacity() {
    use barcode_pdf417::rs::rs_correct;
    for &(payload, level, full, spec) in RS_CORRUPTIONS.iter() {
        let k = k_for_level(level);
        let mut bad = full.to_vec();
        for &(pos, delta) in spec {
            bad[pos] = ((bad[pos] as u32 + delta as u32) % 929) as u16;
        }
        assert!(!rs_valid(&bad, k), "{:?} must be detected corrupt", payload);
        let (fixed, fixes) = rs_correct(&bad, k)
            .unwrap_or_else(|| panic!("{:?}: correction failed", payload));
        assert_eq!(fixed, full, "{:?} corrected stream", payload);
        assert_eq!(fixes.len(), spec.len(), "{:?} fix count", payload);
        assert!(rs_valid(&fixed, k), "{:?} corrected valid", payload);
    }
}


