fn build_canvas(case: &GoldenCase, qz: usize, up: usize, cw: usize, ch: usize,
                flips: &[(usize, usize)]) -> Vec<u8> {
    let src: Vec<u8> = case.matrix.split("\n")
        .flat_map(|line| line.chars().map(|c| if c == '#' { 1u8 } else { 0 }))
        .collect();
    let sw = case.w * up;
    let sh = case.h * up;
    assert_eq!(sw + 2 * qz, cw);
    assert_eq!(sh + 2 * qz, ch);
    let mut canvas = vec![0u8; cw * ch];
    for my in 0..case.h {
        for mx in 0..case.w {
            let v = src[my * case.w + mx];
            for dy in 0..up {
                for dx in 0..up {
                    canvas[(qz + my * up + dy) * cw + qz + mx * up + dx] = v;
                }
            }
        }
    }
    for &(x, y) in flips {
        canvas[y * cw + x] ^= 1;
    }
    canvas
}

#[test]
fn detector_reads_padded_frames() {
    use barcode_pdf417::read_frame;
    for &(ci, qz, up, cw, ch, flips) in DETECT_VECTORS.iter() {
        let case = &CASES[ci];
        let canvas = build_canvas(case, qz, up, cw, ch, flips);
        let got = read_frame(&canvas, cw, ch)
            .unwrap_or_else(|| panic!("{:?}: qz {} up {} flips {}: no decode",
                                     case.payload, qz, up, flips.len()))
            .payload;
        assert_eq!(got, case.payload.as_bytes(), "{:?} payload", case.payload);
    }
}

/// Sheared synthetic fixture: the scanline parser assumes near-horizontal
/// symbol rows, so a phone photo of a landscape symbol (the KLM boarding
/// pass: 1.86° between the horizontal edges) makes every scanline cross
/// several symbol rows. The quad rectifier must decode the same payload.
/// Rendered at the field geometry: 5 data columns, 3px modules, 2.3° row
/// tilt — row height 9px vs a ~2-row drift across the symbol.
#[test]
fn rectified_reads_sheared_symbol() {
    use barcode_core::BitImage;
    use barcode_pdf417::encode::encode_full_opts;
    use barcode_pdf417::read_frame_rectified;

    let payload = "RECTIFIED SHEAR FIXTURE ".repeat(5);
    let sym = encode_full_opts(payload.as_bytes(), 3, 5).unwrap();
    assert_eq!(sym.cols, 5);
    assert!(sym.rows >= 10, "fixture should be tall enough: {} rows", sym.rows);
    let up = 3usize; // pixels per module
    let qz = 24usize; // quiet zone
    let shear = 0.04f64; // ~2.3°, a phone-at-an-angle row tilt
    let w = sym.width;
    let h = sym.height;
    let slide = (shear * (h * up) as f64).ceil() as usize;
    let cw = qz * 2 + w * up + slide;
    let ch = qz * 2 + h * up;
    let bpr = cw.div_ceil(8).div_ceil(4) * 4;
    let mut packed = vec![0u8; bpr * ch];
    for my in 0..h {
        for mx in 0..w {
            if sym.matrix[my * w + mx] == 0 {
                continue;
            }
            let ox = qz + mx * up + (shear * (my * up) as f64) as usize;
            let oy = qz + my * up;
            for y in oy..oy + up {
                for x in ox..ox + up {
                    packed[y * bpr + (x >> 3)] |= 1 << (x & 7);
                }
            }
        }
    }
    let img = BitImage::new(cw as u32, ch as u32, &packed);

    let hit = read_frame_rectified(&img)
        .unwrap_or_else(|| panic!("rectified path failed on a {:.1}° sheared{}x{} symbol", shear.atan().to_degrees(), w, h));
    assert_eq!(barcode_core::payload_text(&hit.payload), payload);
}
